import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%AA%E3%83%BC%E3%83%88%E3%83%9F%E3%83%BC%E3%83%AB.html","title":"オートミール","lang":"en-US","frontmatter":{},"git":{"createdTime":1759035942000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":3}]},"readingTime":{"minutes":1.55,"words":465},"filePathRelative":"オートミール.md"}`),a={name:`オートミール.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="オートミール" tabindex="-1"><a class="header-anchor" href="#オートミール"><span>オートミール</span></a></h1><ul><li><a href="./食事関連.html">食事関連</a></li><li><a href="./レトルトオートミールリゾット.html">レトルトオートミールリゾット</a></li></ul><p>オートミールを炊いて食べる、という技を覚えて、ここ1年くらいは主食をオートミールにしている。（2025-09-28 (日)）</p><h2 id="オートミールを炊く" tabindex="-1"><a class="header-anchor" href="#オートミールを炊く"><span>オートミールを炊く</span></a></h2><p>粒が残っている、ロールドオートミールというタイプのオートミールに、ヒタヒタより少し多めくらいに水を入れて、電子レンジで2.5分程度でご飯っぽく炊けて、結構美味しい。 1分くらいつける方が良いという話も聞くしたまにやるが、違いは良く分からない。 水が多すぎる失敗が多く、逆に少なすぎる失敗は滅多にないので、 どちらかといえば少なすぎる方向に倒す方が良さそう。</p><p>ロールドオートミールはレアというほどでは無いが探さないと無いくらいのもので、 普通にスーパーなどに行くと細かいタイプ（インスタントタイプ）のものしか無い事も多い。</p><p>細かいタイプのものは炊けない。そして炊いて食べるように調理するとめちゃくちゃ不味い。 たまにロールドオートミールが無い時に細かいオートミールを買ってきて食べる事があるが、 だいたい後悔する。</p><p>オートミールは1kg単位で売っていて保存も効いて食べたい時にすぐに食べられて、そこまで高くもないので、 パック玄米よりもだいぶ優れた主食なんじゃないか、と思い始めている。</p><h2 id="炊いたオートミールの食べ方" tabindex="-1"><a class="header-anchor" href="#炊いたオートミールの食べ方"><span>炊いたオートミールの食べ方</span></a></h2><p>最近は納豆とふりかけをメインに食べている。 ふりかけはいろいろ試しているが味道楽が一番好きかなぁ。</p><p>納豆はかなりあう。納豆オートミールはすごく美味しい。</p><p>あまり運動していない時などは、<a href="./配食サービス.html">配食サービス</a>のおかずを先に食べて、少し落ち着いてからオートミールを食べる事にしている。 これは太らない食生活としては結構上手く行っている気がする。</p><p>逆に疲労が溜まっている時は多めにオートミールを食べている。パック玄米などに感じる糖質が足りてない感じは、この量の調整で結構防げると思っている。</p><h2 id="炊いて食べる視点で見たオートミールの種類いろいろ" tabindex="-1"><a class="header-anchor" href="#炊いて食べる視点で見たオートミールの種類いろいろ"><span>炊いて食べる視点で見たオートミールの種類いろいろ</span></a></h2><p>オートミールはあたりハズレがあるので買ったものをメモしていきたい。</p><h3 id="カークランドシグネチャー-オートミール-4-54kg" tabindex="-1"><a class="header-anchor" href="#カークランドシグネチャー-オートミール-4-54kg"><span>カークランドシグネチャー オートミール 4.54kg</span></a></h3><p><a href="https://hb.afl.rakuten.co.jp/ichiba/5393d869.06e6c00b.5393d86a.ce2352a1/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Futopia-style%2Fks-oats4%2F&amp;link_type=hybrid_url&amp;ut=eyJwYWdlIjoiaXRlbSIsInR5cGUiOiJoeWJyaWRfdXJsIiwic2l6ZSI6IjI0MHgyNDAiLCJuYW0iOjEsIm5hbXAiOiJyaWdodCIsImNvbSI6MSwiY29tcCI6ImRvd24iLCJwcmljZSI6MSwiYm9yIjoxLCJjb2wiOjEsImJidG4iOjEsInByb2QiOjAsImFtcCI6ZmFsc2V9" target="_blank" rel="noopener noreferrer">楽天: カークランドシグネチャー オートミール 4.54kg コストコ </a></p><p>4.54kgで3170円。</p><p>オーケーにロールドオートミールが入らなくなってまぁまぁ早く欲しかったので楽天で購入。5/6の夕方にポチって2026-05-08 (金) に到着なので２日くらいか。 4.54kgはでかい。が単価は割と安い。 なんか米を5kgとか買っていた頃を思い出すな。そういえばこういう感じだった。</p><p>試しにレンジで3分で炊いてみた。少し見た目はベチャッとしていたが食べた感じは結構美味しく炊けている。 もう少し長くチンしたり水につけたりを試したい所。</p><p>追記: 4分で炊くといい感じ。悪くはない。</p><h3 id="ツルハドラッグのロールドオートミール" tabindex="-1"><a class="header-anchor" href="#ツルハドラッグのロールドオートミール"><span>ツルハドラッグのロールドオートミール</span></a></h3><p>奄美大島の宿のそばにあるイレブンドラッグで売ってる奴。これまで食べた中で一番美味しい。 ただ鎌倉の家のそばでは売ってない。ぐぬぬ。</p><p><a href="https://shop.tsuruha.co.jp/10162287.html" target="_blank" rel="noopener noreferrer">※ツルハグループ限定※　日本食品製造 日食 管理栄養士おすすめ オートミール ロールドタイプ (1000g) シリアル ヘルシー食品 食物繊維　※軽減税率対象商品-ヘルシーフード</a></p><p>これかな？</p><h3 id="okストア、peace-liverのロールドオートミール" tabindex="-1"><a class="header-anchor" href="#okストア、peace-liverのロールドオートミール"><span>OKストア、Peace Liverのロールドオートミール</span></a></h3><p>なんか近場のOKストアで売ってたオートミールが1kgが300円くらいで売ってて、試しに買ってみたらかなり美味しかった。 これでいいじゃん。</p><p>という事で以後はこれにしよう、と思ったのがこのページを作ろうと思ったきっかけだったりする。 ただOKにしか無いしたまに売り切れている事もあるので、条件を満たせば、という感じ。</p><p>炊き方は少しコツがあって、水をギリギリひたひたくらいの少なめにして、5分くらいの長めのレンジにかけると良い。 3分くらいでは駄目。</p><h3 id="ケロッグ-粒感しっかり-オートミールごはん" tabindex="-1"><a class="header-anchor" href="#ケロッグ-粒感しっかり-オートミールごはん"><span>ケロッグ 粒感しっかり オートミールごはん</span></a></h3><p><a href="https://amzn.to/4ntmqZ4" target="_blank" rel="noopener noreferrer">amazon: ケロッグ 粒感しっかり オートミールごはん</a></p><p>現在（2025-09-28 (日)）Amazonの定期お得便で買っているもの。 900gで1021円。ちょっと高いが、割と美味しい。</p><p>オートミールに疲れてきた時に、ちょっと高くていいので美味しいのは無いかな〜と思ってたどり着いたもの。 ネットで買える主食としてはこれでいいかな、という結論に落ち着いている。</p><p>ロールドオートミールでもっと安いものは他にもあるので、そのうち他のも試したい。</p><h3 id="勅使川原精麦所-オートミール-ロールドオーツ" tabindex="-1"><a class="header-anchor" href="#勅使川原精麦所-オートミール-ロールドオーツ"><span>勅使川原精麦所 オートミール ロールドオーツ</span></a></h3><p><a href="https://amzn.to/4mwNmWp" target="_blank" rel="noopener noreferrer">amazon: 勅使川原精麦所 オートミール ロールドオーツ </a></p><p>こちらは1kg 864円で、以前はこれをAmazon定期便で買っていた。 食べられない訳では無いのだがしばらく続けていたら辛くなってきたので上のケロッグのに乗り換えた。</p><h3 id="日食-プレミアムピュアオートミール" tabindex="-1"><a class="header-anchor" href="#日食-プレミアムピュアオートミール"><span>日食 プレミアムピュアオートミール</span></a></h3><p><a href="https://amzn.to/485wySX" target="_blank" rel="noopener noreferrer">amazon: 日食 プレミアム ピュア オートミール</a></p><p>これはロールドじゃない奴。割とどこのドラッグストアやスーパーでも売ってる、一番入手性が良いオートミールだと思う。 オートミールを切らした時に一時的にこれで凌ぐ、というのはちょくちょくやるが、炊いて食べると毎回後悔する。</p><p>これをいい感じで食べる方法があると小回りは効いて良い気もする。</p>`,41)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};